---- MONITORS ----
------------------

-- See https://wiki.hypr.land/configuring/core/monitors/
hl.monitor({
    output   = "",
    mode     = "highres@highrr",
    position = "auto",
    scale    = 1.0,
})


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use (Native GNOME / GIO dynamic resolvers)
local terminal    = "$HOME/.config/hypr/scripts/terminal.sh"
local browser     = "sh -c 'if command -v gio >/dev/null 2>&1; then exec gio open https://; else exec xdg-open https://; fi'"
local fileManager = "sh -c 'if command -v nautilus >/dev/null 2>&1; then exec nautilus ~; elif command -v gio >/dev/null 2>&1; then exec gio open ~; else exec xdg-open ~; fi'"
local editor      = "sh -c 'gtk-launch $(xdg-mime query default text/plain 2>/dev/null) 2>/dev/null || exec gnome-text-editor \"$@\"'"
local writer      = "sh -c 'gtk-launch $(xdg-mime query default application/vnd.oasis.opendocument.text 2>/dev/null) 2>/dev/null || exec libreoffice --writer \"$@\"'"
local office      = writer
local menu        = "$HOME/.config/hypr/scripts/launcher-apps.sh"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/configuring/core/autostart/

-- Autostart necessary processes (like notifications daemons, status bars, launchers, etc.)
hl.on("hyprland.start", function () 
  hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
  hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
  hl.exec_cmd("$HOME/.config/hypr/scripts/import-gnome-theme.sh")
  hl.exec_cmd("sh -c 'if command -v hyprpolkitagent >/dev/null 2>&1; then hyprpolkitagent; elif [ -x /usr/libexec/hyprpolkitagent ]; then /usr/libexec/hyprpolkitagent; elif [ -x /usr/lib/hyprpolkitagent ]; then /usr/lib/hyprpolkitagent; elif [ -x /usr/libexec/polkit-gnome-authentication-agent-1 ]; then /usr/libexec/polkit-gnome-authentication-agent-1; elif [ -x /usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1 ]; then /usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1; elif [ -x /usr/lib/polkit-kde-authentication-agent-1 ]; then /usr/lib/polkit-kde-authentication-agent-1; elif [ -x /usr/libexec/kf6/kpolkitagent ]; then /usr/libexec/kf6/kpolkitagent; fi'")
  hl.exec_cmd("sh -c 'command -v gnome-keyring-daemon >/dev/null 2>&1 && gnome-keyring-daemon --start --components=secrets,pkcs11'")
  hl.exec_cmd("$HOME/.config/hypr/scripts/gpu-detect.sh --apply")
  hl.exec_cmd("sh -c 'command -v hyprlauncher >/dev/null 2>&1 && hyprlauncher -d'")
  hl.exec_cmd("$HOME/.config/hypr/scripts/waybar.sh")
  hl.exec_cmd("sh -c 'command -v swaync >/dev/null 2>&1 && swaync'")
  hl.exec_cmd("$HOME/.config/hypr/scripts/wallpaper-init.sh")
  hl.exec_cmd("sh -c 'command -v hypridle >/dev/null 2>&1 && hypridle'")
  hl.exec_cmd("sh -c '$HOME/.config/hypr/scripts/clipboard-daemon.sh'")
  hl.exec_cmd("sh -c 'command -v quickshell >/dev/null 2>&1 && quickshell -p $HOME/.config/omalt-tab'")
  hl.exec_cmd("sh -c 'command -v nm-applet >/dev/null 2>&1 && nm-applet --indicator'")
  hl.exec_cmd("sh -c '$HOME/.config/hypr/scripts/session-cleanup.sh &'")
end)


