-- Refined Bezier Curves
hl.curve("overshot",       { type = "bezier", points = { {0.05, 0.9},  {0.1, 1.05}  } })
hl.curve("smoothOut",      { type = "bezier", points = { {0.25, 1},    {0.5, 1}     } })
hl.curve("fluent",         { type = "bezier", points = { {0.1, 1},     {0, 1}       } })
hl.curve("throw",          { type = "bezier", points = { {0.4, 0},     {0.2, 1}     } })
hl.curve("magic",          { type = "bezier", points = { {0.16, 1},    {0.3, 1}     } })
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
