hl.bind(mainMod .. " + Right", hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/window-control.sh right"))
hl.bind(mainMod .. " + H",     hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/window-control.sh minimize"))
hl.bind(mainMod .. " + ALT + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + ALT + right", hl.dsp.focus({ direction = "right" }))
