-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Hyprlauncher & Rofi window rules
hl.window_rule({
    name  = "hyprlauncher-float",
    match = { class = "hyprlauncher" },
    float = true,
})

hl.window_rule({
    name  = "rofi-float",
    match = { class = "rofi" },
    float = true,
})

-- Small & Big float window rules (for nmtui, bluetooth, cheatsheet, etc.)
hl.window_rule({
    name  = "small-float-class",
    match = { class = "small_float" },
    float = true,
    size  = "680 440",
    center = true,
})

hl.window_rule({
    name  = "big-float-class",
    match = { class = "big_float" },
    float = true,
    size  = "1200 780",
    center = true,
})

hl.window_rule({
    name  = "small-float-title-nmtui",
    match = { title = "nmtui" },
    float = true,
    size  = "680 440",
    center = true,
})

hl.window_rule({
    name  = "small-float-title-bluetooth",
    match = { title = "bluetoothctl" },
    float = true,
    size  = "680 440",
    center = true,
})

hl.window_rule({
    name  = "small-float-title-bluetuith",
    match = { title = "bluetuith" },
    float = true,
    size  = "680 440",
    center = true,
})

-- Layer rules for Blur & Opacity
hl.layer_rule({
    name = "wofi-blur",
    match = { namespace = "wofi" },
    blur = true,
    ignore_alpha = 0.1,
})

hl.layer_rule({
    name = "waybar-blur",
    match = { namespace = "waybar" },
    blur = true,
    ignore_alpha = 0.1,
})

hl.layer_rule({
    name = "hyprlauncher-blur",
    match = { namespace = "hyprlauncher" },
    blur = true,
    ignore_alpha = 0.1,
})

hl.layer_rule({
    name = "swaync-control-center-blur",
    match = { namespace = "swaync-control-center" },
    blur = true,
    ignore_alpha = 0.1,
})

hl.layer_rule({
    name = "swaync-notification-window-blur",
    match = { namespace = "swaync-notification-window" },
    blur = true,
    ignore_alpha = 0.1,
})
